// function to traverse the tree
function traverseTree(node, path) {
  if (node.value) {
    path.push(node.value);
    return path;
  }

  for (let i = 0; i < node.children.length; i++) {
    path.push(...traverseTree(node.children[i], path));
  }

  return path;
}

// function to find the longest path
function findLongestPath(path) {
  let longest = 0;
  for (let i = 0; i < path.length; i++) {
    if (path[i].value.length > longest) {
      longest = path[i].value.length;
    }
  }
  return longest;
}

// function to get the shortest path
function getShortestPath(path) {
  let shortest = Infinity;
  for (let i = 0; i < path.length; i++) {
    if (path[i].value.length < shortest) {
      shortest = path[i].value.length;
    }
  }
  return shortest;
}

